$窗口代码 = @'
using System;
using System.Runtime.InteropServices;
using System.Windows.Forms;

public class 卡片面板 : Panel {
    public 卡片面板() { DoubleBuffered = true; }
}

public class 滚轮过滤器 : IMessageFilter {
    public Func<int, bool> 滚轮;
    public bool PreFilterMessage(ref Message 消息) {
        if (消息.Msg == 0x020A && 滚轮 != null) {
            int 增量 = (short)(((long)消息.WParam >> 16) & 0xFFFF);
            return 滚轮(增量);
        }
        return false;
    }
}

public class 窗口效果 {
    [DllImport("dwmapi.dll")] public static extern int DwmSetWindowAttribute(IntPtr 窗口, int 属性, ref int 值, int 大小);
    [DllImport("user32.dll")] public static extern bool ReleaseCapture();
    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr 窗口, int 消息, IntPtr 参数一, IntPtr 参数二);
    [DllImport("user32.dll")] public static extern bool DestroyIcon(IntPtr 图标);
}

[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
public struct 文件信息 {
    public IntPtr hIcon;
    public int iIcon;
    public uint dwAttributes;
    [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 260)] public string szDisplayName;
    [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 80)] public string szTypeName;
}

[ComImport, Guid("46EB5926-582E-4017-9FDF-E8998DAA0950"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
public interface IImageList {
    [PreserveSig] int Add(IntPtr hbmImage, IntPtr hbmMask, ref int pi);
    [PreserveSig] int ReplaceIcon(int i, IntPtr hicon, ref int pi);
    [PreserveSig] int SetOverlayImage(int iImage, int iOverlay);
    [PreserveSig] int Replace(int i, IntPtr hbmImage, IntPtr hbmMask);
    [PreserveSig] int AddMasked(IntPtr hbmImage, int crMask, ref int pi);
    [PreserveSig] int Draw(IntPtr pimldp);
    [PreserveSig] int Remove(int i);
    [PreserveSig] int GetIcon(int i, int flags, ref IntPtr picon);
}

public class 系统图标 {
    [DllImport("shell32.dll", CharSet = CharSet.Unicode)]
    static extern IntPtr SHGetFileInfo(string 路径, uint 属性, ref 文件信息 信息, uint 大小, uint 标志);
    [DllImport("shell32.dll", EntryPoint = "#727")]
    static extern int SHGetImageList(int 表号, ref Guid 接口, out IImageList 列表);

    public static IntPtr 取超大图标(string 路径) {
        文件信息 信息 = new 文件信息();
        IntPtr 结果 = SHGetFileInfo(路径, 0, ref 信息, (uint)Marshal.SizeOf(typeof(文件信息)), 0x4000);
        if (结果 == IntPtr.Zero) return IntPtr.Zero;
        Guid 标识 = typeof(IImageList).GUID;
        IImageList 列表;
        if (SHGetImageList(4, ref 标识, out 列表) != 0) return IntPtr.Zero;
        IntPtr 图标 = IntPtr.Zero;
        if (列表.GetIcon(信息.iIcon, 0x1, ref 图标) != 0) return IntPtr.Zero;
        return 图标;
    }
}
'@
$引用 = @('System.Windows.Forms')
if ($PSVersionTable.PSEdition -eq 'Core') {
    $引用 += 'System.ComponentModel.Primitives'
    $引用 += 'System.Drawing.Primitives'
    $引用 += 'System.Windows.Forms.Primitives'
}
if (-not ([System.Management.Automation.PSTypeName]'系统图标').Type) {
    Add-Type -TypeDefinition $窗口代码 -ReferencedAssemblies $引用
}

$图标池文本 = @'








'@
$script:图标池 = @()
foreach ($图标行 in ($图标池文本 -split "`n")) {
    $图标行 = $图标行.Trim()
    if (-not $图标行) { continue }
    $字节 = [Convert]::FromBase64String($图标行)
    $内存 = New-Object System.IO.MemoryStream(,$字节)
    $script:图标池 += [System.Drawing.Image]::FromStream($内存)
}

