function 取进程显存($样本参数 = $null) {
    $样本 = $样本参数
    if ($null -eq $样本) {
        try { $样本 = (Get-Counter '\GPU Process Memory(*)\Dedicated Usage', '\GPU Process Memory(*)\Shared Usage' -ErrorAction Stop).CounterSamples }
        catch { return @() }
    }

    $专用表 = @{}
    $共享表 = @{}
    foreach ($项 in $样本) {
        if ($项.InstanceName -notmatch '^pid_(\d+)') { continue }
        $进程号 = [int]$Matches[1]
        $兆值 = [math]::Round($项.CookedValue / 1MB, 1)
        if ($项.Path -match 'dedicated') { $专用表[$进程号] = [double]$专用表[$进程号] + $兆值 }
        elseif ($项.Path -match 'shared') { $共享表[$进程号] = [double]$共享表[$进程号] + $兆值 }
    }

    $结果 = @()
    foreach ($号 in $专用表.Keys) {
        $专用值 = [double]$专用表[$号]
        $共享值 = [double]$共享表[$号]
        if (($专用值 + $共享值) -lt $下限MB) { continue }
        $进程 = $null
        try { $进程 = Get-Process -Id $号 -ErrorAction Stop } catch { }
        $名称 = if ($进程) { $进程.ProcessName } else { 文('已退出') }
        $路径 = ''
        try { if ($进程 -and $进程.Path) { $路径 = $进程.Path } } catch { }
        $结果 += [pscustomobject]@{ 进程号 = $号; 名称 = $名称; 专用 = $专用值; 共享 = $共享值; 路径 = $路径 }
    }
    return @($结果 | Sort-Object -Property 专用 -Descending)
}

function 取整卡($文本参数 = $null) {
    try {
        $文本 = $文本参数
        if ($null -eq $文本 -or "$文本".Trim() -eq '') {
            $文本 = (& nvidia-smi --query-gpu=memory.total,memory.used --format=csv,noheader,nounits 2>$null | Select-Object -First 1)
        }
        if (-not $文本) { return @{ 总 = 0; 用 = 0 } }
        $段 = $文本 -split ','
        return @{ 总 = [double]$段[0].Trim(); 用 = [double]$段[1].Trim() }
    } catch { return @{ 总 = 0; 用 = 0 } }
}

$系统守卫 = @('system','registry','dwm','csrss','wininit','winlogon','services','lsass','smss','fontdrvhost','secure system','memory compression')

function 输出帮助 {
    [Console]::WriteLine('显存管家 v1.01 · 智能体接口')
    [Console]::WriteLine('图形界面：直接双击 显存管家.exe')
    [Console]::WriteLine('只读列表：-后台 -列表 [-结果文件 out.json]')
    [Console]::WriteLine('释放显存：-后台 -目标程序 "chrome,msedge" [-已授权] [-等待秒 1] [-需求MB 12000] [-结果文件 out.json]')
    [Console]::WriteLine('规则：不带 -已授权 只预演；系统核心组件、explorer、智能体宿主始终受保护')
    [Console]::WriteLine('退出码：0 正常，1 有结束失败，2 参数错误')
}

function 输出无人值守结果($结果) {
    if ($结果文件) {
        $json = $结果 | ConvertTo-Json -Depth 6
        [System.IO.File]::WriteAllText($结果文件, $json, (New-Object System.Text.UTF8Encoding($false)))
    }
    [Console]::WriteLine('显存管家 v1.01 · ' + $结果.模式)
    if ($结果.模式 -eq '列表') {
        foreach ($项 in $结果.进程列表) {
            [Console]::WriteLine($项.名称 + ' PID ' + $项.进程号 + ' 专用 ' + $项.专用MB + ' MB')
        }
        [Console]::WriteLine('整卡总MB=' + $结果.整卡总MB + ' 整卡用MB=' + $结果.整卡用MB + ' 空闲MB=' + $结果.空闲MB)
        return
    }
    foreach ($项 in $结果.命中进程) {
        [Console]::WriteLine('命中 ' + $项.名称 + ' PID ' + $项.进程号 + ' 专用 ' + $项.专用MB + ' MB')
    }
    foreach ($名 in $结果.跳过保护) { [Console]::WriteLine('保护跳过 ' + $名) }
    foreach ($句 in $结果.错误) { [Console]::WriteLine('错误 ' + $句) }
    [Console]::WriteLine('释放专用MB=' + $结果.释放专用MB)
    [Console]::WriteLine('整卡前MB=' + $结果.整卡前MB + ' 整卡后MB=' + $结果.整卡后MB)
    [Console]::WriteLine('空闲前MB=' + $结果.空闲前MB + ' 空闲后MB=' + $结果.空闲后MB)
    if ($null -ne $结果.满足) { [Console]::WriteLine('需求MB=' + $结果.需求MB + ' 满足=' + $结果.满足) }
}

function 无人值守 {
    $整卡前 = 取整卡
    $空闲前 = 0
    if ($整卡前.总 -gt 0) { $空闲前 = [int]([Math]::Max(0, ($整卡前.总 - $整卡前.用))) }
    if ($列表) {
        $行 = @(取进程显存)
        $表 = [ordered]@{
            版本 = '1.01'
            时间 = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
            模式 = '列表'
            整卡总MB = [int]$整卡前.总
            整卡用MB = [int]$整卡前.用
            空闲MB = $空闲前
            进程列表 = @()
            错误 = @()
        }
        foreach ($进程 in $行) {
            $表.进程列表 += [ordered]@{ 进程号 = $进程.进程号; 名称 = $进程.名称; 专用MB = [int]$进程.专用; 共享MB = [int]$进程.共享; 路径 = $进程.路径 }
        }
        输出无人值守结果 $表
        return 0
    }
    $目标名 = @($目标程序 -split ',' | ForEach-Object { $_.Trim().ToLower() } | Where-Object { $_ })
    if ($目标名.Count -eq 0) {
        [Console]::WriteLine('未指定目标程序，例如：-目标程序 "chrome,msedge"')
        if ($结果文件) {
            $空 = [ordered]@{ 版本 = '1.01'; 模式 = '参数错误'; 目标 = @(); 命中进程 = @(); 已结束 = @(); 跳过保护 = @(); 释放专用MB = 0; 整卡前MB = 0; 整卡后MB = 0; 空闲前MB = 0; 空闲后MB = 0; 需求MB = 0; 满足 = $null; 等待秒 = 0; 错误 = @('未指定目标程序') }
            [System.IO.File]::WriteAllText($结果文件, ($空 | ConvertTo-Json -Depth 6), (New-Object System.Text.UTF8Encoding($false)))
        }
        return 2
    }
    $保护 = @($系统守卫) + @('explorer','pwsh','powershell','windowsterminal','conhost','qoder','qoder cn','node','显存管家')
    $前 = 取进程显存
    $命中 = @($前 | Where-Object { $目标名 -contains $_.名称.ToLower() })
    $计划 = @($命中 | Where-Object { $保护 -notcontains $_.名称.ToLower() })
    $跳过 = @($命中 | Where-Object { $保护 -contains $_.名称.ToLower() } | ForEach-Object { $_.名称 })
    $满足前 = $null
    if ($需求MB -gt 0 -and $整卡前.总 -gt 0) { $满足前 = $空闲前 -ge $需求MB }
    $结果 = [ordered]@{
        版本 = '1.01'
        时间 = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
        模式 = $(if ($已授权) { '执行' } else { '预演' })
        目标 = $目标名
        命中进程 = @()
        已结束 = @()
        跳过保护 = $跳过
        释放专用MB = 0
        整卡前MB = [int]$整卡前.用
        整卡后MB = [int]$整卡前.用
        空闲前MB = $空闲前
        空闲后MB = $空闲前
        需求MB = $需求MB
        满足 = $满足前
        等待秒 = $等待秒
        错误 = @()
    }
    foreach ($进程 in $计划) {
        $结果.命中进程 += [ordered]@{ 进程号 = $进程.进程号; 名称 = $进程.名称; 专用MB = [int]$进程.专用; 共享MB = [int]$进程.共享 }
    }
    if (-not $已授权) {
        $和 = ($计划 | Measure-Object -Property 专用 -Sum).Sum
        if ($null -eq $和) { $和 = 0 }
        $结果.释放专用MB = [int]$和
        输出无人值守结果 $结果
        return 0
    }
    foreach ($进程 in $计划) {
        try {
            Stop-Process -Id $进程.进程号 -Force -ErrorAction Stop
            $结果.已结束 += $进程.名称
        } catch {
            $结果.错误 += ($进程.名称 + ': ' + $_.Exception.Message)
        }
    }
    if ($等待秒 -gt 0) { Start-Sleep -Seconds $等待秒 }
    $整卡后 = 取整卡
    $空闲后 = 0
    if ($整卡后.总 -gt 0) { $空闲后 = [int]([Math]::Max(0, ($整卡后.总 - $整卡后.用))) }
    $结果.整卡后MB = [int]$整卡后.用
    $结果.空闲后MB = $空闲后
    if ($需求MB -gt 0 -and $整卡后.总 -gt 0) { $结果.满足 = $空闲后 -ge $需求MB }
    $已结束和 = ($计划 | Where-Object { $结果.已结束 -contains $_.名称 } | Measure-Object -Property 专用 -Sum).Sum
    if ($null -eq $已结束和) { $已结束和 = 0 }
    $结果.释放专用MB = [int]$已结束和
    输出无人值守结果 $结果
    if ($结果.错误.Count -gt 0) { return 1 }
    return 0
}

if ($帮助) {
    输出帮助
    [Environment]::Exit(0)
}

if ($后台) {
    $无人值守码 = 无人值守
    [Environment]::Exit($无人值守码)
}

$script:简介缓存 = @{}
function 友好简介($名称, $路径) {
    $键 = "$名称|$路径|$($script:实际语言)"
    if ($script:简介缓存.ContainsKey($键)) { return $script:简介缓存[$键] }
    $对照 = $script:简介表[$script:实际语言]
    if (-not $对照) { $对照 = @{} }
    $简介 = $对照[$名称.ToLower()]
    if (-not $简介 -and $路径) {
        try {
            $版本信息 = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($路径)
            if ($版本信息.FileDescription -and $版本信息.FileDescription -ne $名称) { $简介 = $版本信息.FileDescription.Trim() }
        } catch { }
    }
    if (-not $简介) { $简介 = 文('Windows进程') }
    $script:简介缓存[$键] = $简介
    return $简介
}

$script:图标缓存 = @{}
function 缩图($源) {
    $图 = New-Object System.Drawing.Bitmap(56, 56)
    $绘 = [System.Drawing.Graphics]::FromImage($图)
    $绘.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $绘.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $绘.DrawImage($源, (New-Object System.Drawing.Rectangle(0, 0, 56, 56)))
    $绘.Dispose()
    return $图
}
function 取图标($路径, $进程号) {
    $用路径 = ($路径 -and (Test-Path -LiteralPath $路径))
    $键 = if ($用路径) { $路径 } else { '池:' + ($进程号 % $script:图标池.Count) }
    if ($script:图标缓存.ContainsKey($键)) { return $script:图标缓存[$键] }
    $图 = $null
    if ($用路径) {
        try {
            $句柄 = [系统图标]::取超大图标($路径)
            if ($句柄 -ne [IntPtr]::Zero) {
                $图标 = [System.Drawing.Icon]::FromHandle($句柄)
                $大图 = $图标.ToBitmap()
                [窗口效果]::DestroyIcon($句柄) | Out-Null
                $图 = 缩图 $大图
                $大图.Dispose()
            }
        } catch { $图 = $null }
    }
    if (-not $图) { $图 = 缩图 $script:图标池[[int]($进程号 % $script:图标池.Count)] }
    $script:图标缓存[$键] = $图
    return $图
}

function 圆角路径([System.Drawing.Rectangle]$矩形, [int]$半径) {
    $路径 = New-Object System.Drawing.Drawing2D.GraphicsPath
    $直径 = $半径 * 2
    if ($直径 -gt $矩形.Width) { $直径 = $矩形.Width }
    if ($直径 -gt $矩形.Height) { $直径 = $矩形.Height }
    $路径.AddArc($矩形.X, $矩形.Y, $直径, $直径, 180, 90)
    $路径.AddArc($矩形.Right - $直径, $矩形.Y, $直径, $直径, 270, 90)
    $路径.AddArc($矩形.Right - $直径, $矩形.Bottom - $直径, $直径, $直径, 0, 90)
    $路径.AddArc($矩形.X, $矩形.Bottom - $直径, $直径, $直径, 90, 90)
    $路径.CloseFigure()
    return $路径
}
function 填圆角($绘, [System.Drawing.Rectangle]$矩形, [int]$半径, $颜色) {
    $路径 = 圆角路径 $矩形 $半径
    $刷 = New-Object System.Drawing.SolidBrush($颜色)
    $绘.FillPath($刷, $路径)
    $刷.Dispose()
    $路径.Dispose()
}
function 画进度条($绘, [System.Drawing.Rectangle]$矩形, [double]$占比) {
    填圆角 $绘 $矩形 4 $轨道色
    if ($占比 -le 0) { return }
    if ($占比 -gt 1) { $占比 = 1 }
    $条宽 = [int]([math]::Round($矩形.Width * $占比))
    if ($条宽 -lt 8) { $条宽 = 8 }
    $条角 = New-Object System.Drawing.Rectangle($矩形.X, $矩形.Y, $条宽, $矩形.Height)
    $路径 = 圆角路径 $条角 4
    $渐变 = New-Object System.Drawing.Drawing2D.LinearGradientBrush($条角, $主色, $副色, [System.Drawing.Drawing2D.LinearGradientMode]::Horizontal)
    $绘.FillPath($渐变, $路径)
    $渐变.Dispose()
    $路径.Dispose()
}
function 画文字($绘, $文本, $字体, $颜色, [System.Drawing.RectangleF]$矩形, $对齐) {
    $格式 = New-Object System.Drawing.StringFormat
    $格式.Alignment = $对齐
    $格式.Trimming = [System.Drawing.StringTrimming]::EllipsisCharacter
    $格式.FormatFlags = [System.Drawing.StringFormatFlags]::NoWrap
    $刷 = New-Object System.Drawing.SolidBrush($颜色)
    $绘.DrawString($文本, $字体, $刷, $矩形, $格式)
    $刷.Dispose()
    $格式.Dispose()
}

