function 应用滚动 {
    $序号 = 0
    foreach ($卡 in $script:卡片集) {
        $卡.Top = 12 + $序号 * 106 - $script:滚动量
        $序号++
    }
}
function 重算滚动 {
    $视口 = $滚动区.ClientSize.Height
    $内容 = 12 + $script:卡片集.Count * 106
    $最大 = $内容 - $视口 + 12
    if ($最大 -lt 0) { $最大 = 0 }
    if ($script:滚动量 -gt $最大) { $script:滚动量 = $最大 }
    if ($script:滚动量 -lt 0) { $script:滚动量 = 0 }
    应用滚动
}
function 滚动([int]$增量) {
    $视口 = $滚动区.ClientSize.Height
    $内容 = 12 + $script:卡片集.Count * 106
    $最大 = $内容 - $视口 + 12
    if ($最大 -lt 0) { $最大 = 0 }
    $目标 = $script:滚动量 - ([int]($增量 / 120) * 106)
    if ($目标 -lt 0) { $目标 = 0 }
    if ($目标 -gt $最大) { $目标 = $最大 }
    if ($目标 -eq $script:滚动量) { return }
    $script:滚动量 = $目标
    应用滚动
}
function 同步卡宽 {
    if ($script:卡片集.Count -eq 0) { return }
    $宽 = $滚动区.Width - 24
    if ($宽 -lt 300) { $宽 = 300 }
    foreach ($卡 in $script:卡片集) {
        if ($卡.Width -ne $宽) { $卡.Width = $宽; $卡.Invalidate() }
    }
}
$滚动区.Add_Resize({ 同步卡宽; 重算滚动 })
$滚动区.Add_ClientSizeChanged({ 同步卡宽; 重算滚动 })

$过滤器 = New-Object 滚轮过滤器
$过滤器.滚轮 = [Func[int,bool]]{
    param([int]$增量)
    if (-not $窗体.Visible) { return $false }
    if ([System.Windows.Forms.Form]::ActiveForm -ne $窗体) { return $false }
    $点 = $滚动区.PointToClient([System.Windows.Forms.Cursor]::Position)
    if (-not $滚动区.ClientRectangle.Contains($点)) { return $false }
    滚动 $增量
    return $true
}
[System.Windows.Forms.Application]::AddMessageFilter($过滤器)

function 圆角钮($文本, [int]$宽, $背景, $前景) {
