    $钮.Region = New-Object System.Drawing.Region($路径)
    $路径.Dispose()
    return $钮
}

function 消息窗($标题文本, $正文, $模式, $警示 = '') {
    $对话框 = New-Object System.Windows.Forms.Form
    $对话框.FormBorderStyle = 'None'
    $对话框.StartPosition = 'CenterParent'
    $对话框.BackColor = $底色
    $对话框.ShowInTaskbar = $false
    $对话框.Font = $字说明

    $正文宽 = 372
    $测量绘 = $对话框.CreateGraphics()
    $测量 = $测量绘.MeasureString($正文, $字说明, $正文宽)
    $测量绘.Dispose()
    $正文高 = [int][Math]::Ceiling($测量.Height) + 4
    if ($正文高 -lt 20) { $正文高 = 20 }
    if ($正文高 -gt 260) { $正文高 = 260 }
    $警示高 = 0
    if ($模式 -eq 'danger') {
        $警示测量绘 = $对话框.CreateGraphics()
        $警示测量 = $警示测量绘.MeasureString($警示, $字说明, 348)
        $警示测量绘.Dispose()
        $警示高 = [int][Math]::Ceiling($警示测量.Height) + 4
        if ($警示高 -lt 20) { $警示高 = 20 }
        if ($警示高 -gt 140) { $警示高 = 140 }
    }
    $总高 = 20 + 26 + 12 + $正文高 + 24 + 40 + 20
    if ($警示高 -gt 0) { $总高 = $总高 + $警示高 + 28 }
    $对话框.Size = New-Object System.Drawing.Size(420, $总高)

    $圆点色 = $主色
    if ($模式 -eq 'ask') { $圆点色 = [System.Drawing.Color]::FromArgb(255, 176, 32) }
    if ($模式 -eq 'stop') { $圆点色 = [System.Drawing.Color]::FromArgb(224, 68, 68) }
    if ($模式 -eq 'danger') { $圆点色 = [System.Drawing.Color]::FromArgb(224, 68, 68) }
    $圆点 = New-Object System.Windows.Forms.Panel
    $圆点.Size = New-Object System.Drawing.Size(10, 10)
    $圆点.Location = New-Object System.Drawing.Point(24, 28)
    $圆点.BackColor = $圆点色
    $圆路径 = 圆角路径 (New-Object System.Drawing.Rectangle(0, 0, 10, 10)) 5
    $圆点.Region = New-Object System.Drawing.Region($圆路径)
    $圆路径.Dispose()

    $标题签 = New-Object System.Windows.Forms.Label
    $标题签.Text = $标题文本
    $标题签.Font = $字名称
    $标题签.ForeColor = $主字色
    $标题签.AutoSize = $true
    $标题签.Location = New-Object System.Drawing.Point(42, 20)

    $正文签 = New-Object System.Windows.Forms.Label
    $正文签.Text = $正文
    $正文签.Font = $字说明
    $正文签.ForeColor = $次字色
    $正文签.Size = New-Object System.Drawing.Size($正文宽, $正文高)
    $正文签.Location = New-Object System.Drawing.Point(24, 58)

    $对话框.Controls.AddRange(@($圆点, $标题签, $正文签))

    if ($模式 -eq 'danger') {
        $警示框 = New-Object System.Windows.Forms.Panel
        $警示框.Size = New-Object System.Drawing.Size(372, ($警示高 + 16))
        $警示框.Location = New-Object System.Drawing.Point(24, (58 + $正文高 + 10))
        $警示框.BackColor = $底色
        $警示框.Add_Paint({
            param($发送者, $事件)
            $绘 = $事件.Graphics
            $绘.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $矩形 = New-Object System.Drawing.Rectangle(1, 1, ($发送者.Width - 3), ($发送者.Height - 3))
            $路径 = 圆角路径 $矩形 10
            $刷 = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(58, 22, 24))
            $绘.FillPath($刷, $路径)
            $刷.Dispose()
            $笔 = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(224, 68, 68), 1.5)
            $绘.DrawPath($笔, $路径)
            $笔.Dispose()
            $路径.Dispose()
        })
        $警示签 = New-Object System.Windows.Forms.Label
        $警示签.Text = $警示
        $警示签.Font = $字说明
        $警示签.ForeColor = [System.Drawing.Color]::FromArgb(255, 205, 205)
        $警示签.BackColor = [System.Drawing.Color]::Transparent
        $警示签.Size = New-Object System.Drawing.Size(348, $警示高)
        $警示签.Location = New-Object System.Drawing.Point(12, 8)
        $警示框.Controls.Add($警示签)
        $对话框.Controls.Add($警示框)
    }

    if ($模式 -eq 'danger') {
        $取消钮 = 圆角钮 (文('取消')) 96 $按钮色 $次字色
        $取消钮.Location = New-Object System.Drawing.Point(172, ($总高 - 60))
        $取消钮.DialogResult = 'No'
        $取消钮.Add_MouseEnter({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $悬停色; $发送者.ForeColor = $主字色 } })
        $取消钮.Add_MouseLeave({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $按钮色; $发送者.ForeColor = $次字色 } })
        $危险钮 = 圆角钮 (文('仍然结束')) 116 ([System.Drawing.Color]::FromArgb(196, 48, 48)) ([System.Drawing.Color]::White)
        $危险钮.Location = New-Object System.Drawing.Point(280, ($总高 - 60))
        $危险钮.DialogResult = 'Yes'
        $危险钮.Add_MouseEnter({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = [System.Drawing.Color]::FromArgb(224, 68, 68) } })
        $危险钮.Add_MouseLeave({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = [System.Drawing.Color]::FromArgb(196, 48, 48) } })
        $对话框.Controls.AddRange(@($取消钮, $危险钮))
        $对话框.AcceptButton = $取消钮
        $对话框.CancelButton = $取消钮
    } elseif ($模式 -eq 'ask') {
        $确认钮 = 圆角钮 (文('结束')) 96 ([System.Drawing.Color]::FromArgb(196, 48, 48)) ([System.Drawing.Color]::White)
        $确认钮.Location = New-Object System.Drawing.Point(300, ($总高 - 60))
        $确认钮.DialogResult = 'Yes'
        $确认钮.Add_MouseEnter({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = [System.Drawing.Color]::FromArgb(224, 68, 68) } })
        $确认钮.Add_MouseLeave({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = [System.Drawing.Color]::FromArgb(196, 48, 48) } })
        $取消钮 = 圆角钮 (文('取消')) 96 $按钮色 $次字色
        $取消钮.Location = New-Object System.Drawing.Point(192, ($总高 - 60))
        $取消钮.DialogResult = 'No'
        $取消钮.Add_MouseEnter({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $悬停色; $发送者.ForeColor = $主字色 } })
        $取消钮.Add_MouseLeave({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $按钮色; $发送者.ForeColor = $次字色 } })
        $对话框.Controls.AddRange(@($取消钮, $确认钮))
        $对话框.AcceptButton = $确认钮
        $对话框.CancelButton = $取消钮
    } else {
        $知道钮 = 圆角钮 (文('知道了')) 96 $按钮色 $主字色
        $知道钮.Location = New-Object System.Drawing.Point(300, ($总高 - 60))
        $知道钮.DialogResult = 'OK'
        $知道钮.Add_MouseEnter({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $悬停色 } })
        $知道钮.Add_MouseLeave({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $按钮色 } })
        $对话框.Controls.Add($知道钮)
        $对话框.AcceptButton = $知道钮
        $对话框.CancelButton = $知道钮
    }

    $对话框.Add_Shown({
        param($发送者, $事件)
        $圆角值 = 2
        [窗口效果]::DwmSetWindowAttribute($发送者.Handle, 33, [ref]$圆角值, 4) | Out-Null
    })
    $选择 = $对话框.ShowDialog($窗体)
    $对话框.Dispose()
