}

[System.Windows.Forms.Application]::add_ThreadException({
    param($发送者, $事件)
    消息窗 (文('出错')) $事件.Exception.Message 'stop' | Out-Null
})

function 结束进程($进程) {
    $是系统 = ($系统守卫 -contains $进程.名称.ToLower())
    if ($是系统) {
        $后果 = 文('后果通用')
        if ($进程.名称.ToLower() -eq 'dwm') { $后果 = 文('后果dwm') }
        if ($进程.名称.ToLower() -eq 'explorer') { $后果 = 文('后果explorer') }
        $选择 = 消息窗 (文('危险操作')) ((文('确认系统格式')) -f $进程.名称, $进程.进程号) 'danger' $后果
    } else {
        $选择 = 消息窗 (文('结束进程')) (((文('确认结束格式')) -f $进程.名称, $进程.进程号) + "`n" + (文('未保存'))) 'ask'
    }
    if ($选择 -ne 'Yes') { return }
    try {
        Stop-Process -Id $进程.进程号 -Force -ErrorAction Stop
        Start-Sleep -Milliseconds 400
        $script:上次签名 = ''
        重填
    } catch {
        消息窗 (文('结束失败')) ((文('需管理员')) + "`n" + $_.Exception.Message) 'stop' | Out-Null
    }
}

function 造卡($进程, [int]$宽) {
    $卡 = New-Object 卡片面板
    $卡.Size = New-Object System.Drawing.Size($宽, 96)
    $卡.BackColor = $底色
    $卡.Cursor = 'Hand'

    $图标 = 取图标 $进程.路径 $进程.进程号
    $简介 = 友好简介 $进程.名称 $进程.路径
    if ($script:同名数[$进程.名称] -gt 1) { $简介 += ' · PID {0}' -f $进程.进程号 }
    $占比 = 0
    $百分比 = '--'
    if ($script:显卡.总 -gt 0) { $占比 = $进程.专用 / $script:显卡.总; $百分比 = '{0:N1}%' -f ($占比 * 100) }
    $兆 = '{0:N0} MB' -f $进程.专用
    $是系统 = ($系统守卫 -contains $进程.名称.ToLower())
    $卡.Tag = @{ 进程 = $进程; 图标 = $图标; 简介 = $简介; 百分比 = $百分比; 兆 = $兆; 占比 = $占比 }

    $卡.Add_Paint({
        param($发送者, $事件)
        $绘 = $事件.Graphics
        $绘.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $绘.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $资料 = $发送者.Tag
        $行 = $资料.进程
        $背景 = $卡片色
        if ($script:悬停进程 -eq $行.进程号) { $背景 = $悬停色 }
        $矩形 = New-Object System.Drawing.Rectangle(0, 0, ($发送者.Width - 1), 95)
        填圆角 $绘 $矩形 14 $背景
        if ($script:选中进程 -eq $行.进程号) {
            $选中路径 = 圆角路径 $矩形 14
            $选中笔 = New-Object System.Drawing.Pen($主色, 1.6)
            $绘.DrawPath($选中笔, $选中路径)
            $选中笔.Dispose()
            $选中路径.Dispose()
        }
        if ($资料.图标) { $绘.DrawImage($资料.图标, (New-Object System.Drawing.Rectangle(14, 20, 56, 56))) }
        $文字宽 = $发送者.Width - 178
        if ($文字宽 -lt 120) { $文字宽 = 120 }
        画文字 $绘 $行.名称 $字名称 $主字色 (New-Object System.Drawing.RectangleF(84, 13, $文字宽, 22)) 'Near'
        画文字 $绘 $资料.简介 $字说明 $次字色 (New-Object System.Drawing.RectangleF(84, 37, $文字宽, 16)) 'Near'
        画文字 $绘 $资料.百分比 $字百分比 $副色 (New-Object System.Drawing.RectangleF(84, 61, 62, 18)) 'Near'
        $条宽 = $发送者.Width - 262
        if ($条宽 -lt 80) { $条宽 = 80 }
        画进度条 $绘 (New-Object System.Drawing.Rectangle(150, 66, $条宽, 8)) $资料.占比
        画文字 $绘 $资料.兆 $字兆 $次字色 (New-Object System.Drawing.RectangleF(($发送者.Width - 108), 61, 94, 18)) 'Far'
    })

    $卡.Add_MouseClick({
        param($发送者, $事件)
        $script:选中进程 = $发送者.Tag.进程.进程号
        foreach ($项 in $script:卡片集) { $项.Invalidate() }
    })
    $卡.Add_MouseDoubleClick({ param($发送者, $事件) 结束进程 $发送者.Tag.进程 })
    $卡.Add_MouseEnter({ param($发送者, $事件) $script:悬停进程 = $发送者.Tag.进程.进程号; $发送者.Invalidate() })
    $卡.Add_MouseLeave({ param($发送者, $事件) $script:悬停进程 = -1; $发送者.Invalidate() })
    $script:提示.SetToolTip($卡, "$($进程.路径)`n$(文('专用')) $($进程.专用) MB · $(文('共享')) $($进程.共享) MB")

    $按钮 = New-Object System.Windows.Forms.Button
    $按钮.Size = New-Object System.Drawing.Size(72, 34)
    $按钮.Location = New-Object System.Drawing.Point(($宽 - 86), 10)
    $按钮.Anchor = 'Top,Right'
    $按钮.FlatStyle = 'Flat'
    $按钮.FlatAppearance.BorderSize = 0
    $按钮.Font = $字按钮
    $按钮.Cursor = 'Hand'
    if ($是系统) {
        $按钮.Text = 文('系统')
        $按钮.Enabled = $false
        $按钮.BackColor = $卡片色
        $按钮.ForeColor = [System.Drawing.Color]::FromArgb(110, 114, 120)
    } else {
        $按钮.Text = 文('结束')
        $按钮.BackColor = $按钮色
        $按钮.ForeColor = $次字色
        $按钮.Add_MouseEnter({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = [System.Drawing.Color]::FromArgb(196, 48, 48); $发送者.ForeColor = [System.Drawing.Color]::White } })
        $按钮.Add_MouseLeave({ param($发送者, $事件) if ($发送者 -is [System.Windows.Forms.Control]) { $发送者.BackColor = $按钮色; $发送者.ForeColor = $次字色 } })
        $按钮.Add_Click({ param($发送者, $事件) 结束进程 $发送者.Parent.Tag.进程 })
    }
    $卡.Controls.Add($按钮)
    return $卡
}

function 重填 {
    $进程表 = 取进程显存
    $script:显卡 = 取整卡
    填充 $进程表
}

function 填充($进程表) {
    $script:上次进程表 = $进程表
    if ($script:显卡.总 -gt 0) {
        $头部信息.Text = (文('整卡格式')) -f ($script:显卡.用 / 1024), ($script:显卡.总 / 1024), ($script:显卡.用 / $script:显卡.总 * 100)
    } else {
        $合计 = 0
        foreach ($进程 in $进程表) { $合计 += $进程.专用 }
        $头部信息.Text = (文('未读到格式')) -f $合计
    }
    $顶栏.Invalidate()

    $签名 = (@($进程表 | ForEach-Object { '{0}:{1}' -f $_.进程号, [int]$_.专用 }) -join '|')
    if ($签名 -eq $script:上次签名 -and $script:卡片集.Count -gt 0) {
        $合计 = 0
        foreach ($进程 in $进程表) { $合计 += $进程.专用 }
        $状态.Text = (文('状态格式')) -f $进程表.Count, $合计
        return
    }
    $script:上次签名 = $签名

    $滚动区.SuspendLayout()
    foreach ($旧卡 in $script:卡片集) {
        $滚动区.Controls.Remove($旧卡)
        $旧卡.Dispose()
    }
    $script:卡片集 = @()
    $宽 = $滚动区.Width - 24
    if ($宽 -lt 300) { $宽 = 300 }
    $script:同名数 = @{}
    foreach ($进程 in $进程表) { $script:同名数[$进程.名称] = [int]$script:同名数[$进程.名称] + 1 }
    $序号 = 0
    foreach ($进程 in $进程表) {
        $卡 = 造卡 $进程 $宽
        $卡.Location = New-Object System.Drawing.Point(12, (12 + $序号 * 106 - $script:滚动量))
        $滚动区.Controls.Add($卡)
        $script:卡片集 += $卡
        $序号++
    }
    $滚动区.ResumeLayout()
    同步卡宽
    重算滚动
    $合计 = 0
    foreach ($进程 in $进程表) { $合计 += $进程.专用 }
    $状态.Text = (文('状态格式')) -f $进程表.Count, $合计
}

function 设置语言($代码) {
    $script:语言选择 = $代码
    存设置
    $script:实际语言 = 解析语言 $代码
    $script:简介缓存 = @{}
    $script:上次签名 = ''
    $窗体.Text = 文('应用名')
    $标题.Text = 文('应用名')
    $语言钮.Text = 文('语言')
    if ($script:上次进程表 -and @($script:上次进程表).Count -gt 0) {
        填充 $script:上次进程表
    } else {
        $头部信息.Text = 文('读取中')
        $状态.Text = 文('就绪')
    }
}

