    )
    $序 = 0
    foreach ($项 in $项表) {
        $行 = New-Object System.Windows.Forms.Label
        $文字 = $项.文字
        if ($项.代码 -eq $script:语言选择) { $文字 = '● ' + $文字 }
        $行.Text = $文字
        $行.Font = $字说明
        $行.ForeColor = $主字色
        $行.BackColor = $底色
        $行.Cursor = 'Hand'
        $行.TextAlign = 'MiddleLeft'
        $行.Size = New-Object System.Drawing.Size(184, 30)
        $行.Location = New-Object System.Drawing.Point(8, (8 + $序 * 32))
        $行.Tag = $项.代码
        if ($项.代码 -eq $script:语言选择) { $行.ForeColor = $副色 }
        $行.Add_MouseEnter({ param($发送者, $事件) $发送者.BackColor = $悬停色 })
        $行.Add_MouseLeave({ param($发送者, $事件) $发送者.BackColor = $底色 })
        $行.Add_Click({ param($发送者, $事件) 设置语言 $发送者.Tag; if ($script:语言窗) { $script:语言窗.Close() } })
        $菜单.Controls.Add($行)
        $序++
    }
    $按钮矩形 = $语言钮.RectangleToScreen($语言钮.ClientRectangle)
    $菜单.Location = New-Object System.Drawing.Point(($按钮矩形.Right - 200), ($按钮矩形.Bottom + 6))
    $菜单.Add_Deactivate({ param($发送者, $事件) $发送者.Close() })
    $script:语言窗 = $菜单
    $菜单.Show($窗体)
    $菜单.Activate()
}

$窗体.Controls.Add($滚动区)
$窗体.Controls.Add($底栏)
$窗体.Controls.Add($顶栏)

$窗体.Add_Shown({
    param($发送者, $事件)
    $圆角值 = 2
    [窗口效果]::DwmSetWindowAttribute($发送者.Handle, 33, [ref]$圆角值, 4) | Out-Null
})

$窗体.Add_FormClosed({ [System.Windows.Forms.Application]::ExitThread() })

$加载窗 = New-Object System.Windows.Forms.Form
$加载窗.FormBorderStyle = 'None'
$加载窗.StartPosition = 'CenterScreen'
$加载窗.ShowInTaskbar = $false
$加载窗.BackColor = $底色
$加载窗.Size = New-Object System.Drawing.Size(340, 150)
$加载窗.Font = $字说明
$加载窗.TopMost = $true
$缓冲属性 = $加载窗.GetType().GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'NonPublic,Instance')
$缓冲属性.SetValue($加载窗, $true)
$加载窗.Add_Shown({
    param($发送者, $事件)
    $圆角值 = 2
    [窗口效果]::DwmSetWindowAttribute($发送者.Handle, 33, [ref]$圆角值, 4) | Out-Null
})
$script:点相位 = 0
$加载窗.Add_Paint({
    param($发送者, $事件)
    $绘 = $事件.Graphics
    $绘.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $标题刷 = New-Object System.Drawing.SolidBrush($主字色)
    $绘.DrawString((文('应用名')), $字标题, $标题刷, 24, 20)
    $标题刷.Dispose()
    $副刷 = New-Object System.Drawing.SolidBrush($次字色)
    $绘.DrawString((文('加载中')), $字说明, $副刷, 24, 66)
    $副刷.Dispose()
    for ($序 = 0; $序 -lt 3; $序++) {
        $亮度 = 60
        if (($script:点相位 % 3) -eq $序) { $亮度 = 255 }
        $半径 = 3.4 + 1.1 * [Math]::Sin(($script:点相位 * 0.8) + $序)
        $中心X = 196 + $序 * 18
        $中心Y = 74 - 2.4 * [Math]::Sin(($script:点相位 * 0.8) + $序)
        $圆刷 = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb($亮度, $主色.R, $主色.G, $主色.B))
        $绘.FillEllipse($圆刷, [float]($中心X - $半径), [float]($中心Y - $半径), [float]($半径 * 2), [float]($半径 * 2))
        $圆刷.Dispose()
    }
    $轨道 = New-Object System.Drawing.Rectangle(24, 118, 292, 4)
    填圆角 $绘 $轨道 2 $轨道色
    $亮起 = 24 + (($script:点相位 * 16) % 232)
    $段 = New-Object System.Drawing.Rectangle([int]$亮起, 118, 60, 4)
    $段路径 = 圆角路径 $段 2
    $段刷 = New-Object System.Drawing.Drawing2D.LinearGradientBrush($段, $主色, $副色, [System.Drawing.Drawing2D.LinearGradientMode]::Horizontal)
    $绘.FillPath($段刷, $段路径)
    $段刷.Dispose()
    $段路径.Dispose()
})

$动画 = New-Object System.Windows.Forms.Timer
$动画.Interval = 80
$动画.Add_Tick({
    $script:点相位 = $script:点相位 + 1
    $加载窗.Invalidate()
})

$采集代码 = @'
$样本 = @()
try { $样本 = (Get-Counter '\GPU Process Memory(*)\Dedicated Usage', '\GPU Process Memory(*)\Shared Usage' -ErrorAction Stop).CounterSamples } catch { }
$整卡 = ''
try { $整卡 = (& nvidia-smi --query-gpu=memory.total,memory.used --format=csv,noheader,nounits 2>$null | Select-Object -First 1) } catch { }
[pscustomobject]@{ 样本 = $样本; 整卡 = $整卡 }
'@

$后台引擎 = [PowerShell]::Create()
$null = $后台引擎.AddScript($采集代码)
$异步 = $后台引擎.BeginInvoke()

$轮询 = New-Object System.Windows.Forms.Timer
$轮询.Interval = 160
$轮询.Add_Tick({
    if (-not $异步.IsCompleted) { return }
    $轮询.Stop()
    $进程表 = @()
    $整卡文本 = $null
    try {
        $结果 = @($后台引擎.EndInvoke($异步)) | Select-Object -First 1
        if ($结果) {
            $进程表 = 取进程显存 $结果.样本
            $整卡文本 = $结果.整卡
        }
    } catch { }
    if ($进程表.Count -eq 0) {
        $进程表 = 取进程显存
        $整卡文本 = $null
    }
    $script:显卡 = 取整卡 $整卡文本
    try { 填充 $进程表 } catch { }
    $动画.Stop()
    $窗体.Opacity = 0
    $窗体.Show()
    $窗体.Activate()
    $script:渐显 = New-Object System.Windows.Forms.Timer
    $script:渐显.Interval = 15
    $script:渐显.Add_Tick({
        if ($加载窗.Opacity -gt 0.08) { $加载窗.Opacity = $加载窗.Opacity - 0.09 } else { if ($加载窗.Visible) { $加载窗.Close() } }
        if ($窗体.Opacity -lt 0.97) { $窗体.Opacity = $窗体.Opacity + 0.06 }
        else { $窗体.Opacity = 1.0; $script:渐显.Stop() }
    })
    $script:渐显.Start()
    if ($自动关闭秒 -gt 0) {
        $script:计时 = New-Object System.Windows.Forms.Timer
        $script:计时.Interval = $自动关闭秒 * 1000
        $script:计时.Add_Tick({
            $script:计时.Stop()
            $窗体.Close()
        })
        $script:计时.Start()
    }
})

$加载窗.Show()
$动画.Start()
$轮询.Start()
[System.Windows.Forms.Application]::Run()
